const MOONBASE_DATA = SUB_NETWORKS[SubNetworkId.AlphanetMoonbase];
class MoonbaseParachainAdapter extends ParachainAdapter {
  nativeAssetContractAddress = "0x0000000000000000000000000000000000000802";
  xTokensContractAddress = "0x0000000000000000000000000000000000000804";
  // overrides "WithConnectionApi"
  get chainSymbol() {
    return MOONBASE_DATA?.nativeCurrency?.symbol;
  }
  // overrides "WithConnectionApi"
  formatAddress(address, _withPrefix = true) {
    return address;
  }
  // overrides "SubAdapter"
  async connect() {
    await super.connect();
    await this.getAssetsMetadata();
  }
  // overrides "SubAdapter"
  async getAccountAssetBalance(accountAddress, asset2) {
    return await this.assetsAccountRequest(accountAddress, asset2.externalAddress);
  }
  // Assets has not minimal deposit on Moonbase
  // overrides "ParachainAdapter"
  async getAssetDeposit(asset2) {
    return ZeroStringValue;
  }
  // overrides "ParachainAdapter"
  async getAssetIdByMultilocation(asset2, multilocation) {
    const assetType = {
      XCM: multilocation
    };
    const result2 = await this.api.query.assetManager.assetTypeId(assetType);
    if (result2.isEmpty) return "";
    const id2 = result2.unwrap().toString();
    return id2;
  }
  // overrides "ParachainAdapter"
  assetIdToEvmContractAddress(id2) {
    const base3 = new BigNumber(id2).toString(16);
    const padded = base3.padStart(40, "f");
    return `0x${padded}`;
  }
  /**
   * Convert parachain id to xcm junction
   */
  toParachainAddress(id2) {
    const selector = "0x00";
    const address = Number(id2 ?? 0).toString(16).padStart(8, "0");
    return selector + address;
  }
  /**
   * Convert substrate account address to xcm junction
   */
  toAccountId32(address) {
    const selector = "0x01";
    const publicKey = this.getPublicKeyByAddress(address);
    const networkOption = "00";
    return selector + publicKey + networkOption;
  }
  async transfer(asset2, recipient, amount, historyId) {
    const currencyAddress = asset2.symbol === this.chainSymbol ? this.nativeAssetContractAddress : this.assetIdToEvmContractAddress(asset2.externalAddress);
    const value2 = new FPNumber(amount, asset2.externalDecimals).toCodecString();
    const weight = 5e9;
    const parents2 = 1;
    const parachainJunction = this.toParachainAddress(this.getSoraParachainId());
    const accountJunction = this.toAccountId32(recipient);
    const interior = [parachainJunction, accountJunction];
    const destination = [parents2, interior];
    const xTokens = await ethersUtil.getContract(this.xTokensContractAddress, xTokensAbi);
    const signedTx = await xTokens.transfer(currencyAddress, value2, destination, weight);
    updateTransaction(historyId, {
      externalHash: signedTx.hash,
      externalNetworkFee: getEvmTransactionFee(signedTx),
      status: TransactionStatus.InBlock
    });
    await delay();
    onEvmTransactionPending(historyId, getTransaction, updateTransaction).then(() => {
      updateTransaction(historyId, {
        status: TransactionStatus.Finalized
      });
    }).catch(() => {
      updateTransaction(historyId, {
        status: TransactionStatus.Error
      });
    });
  }
}
