    switch (this.subNetwork) {
      case SubNetworkId.Rococo:
        return toCodec2(125e-6);
      case SubNetworkId.Alphanet:
        return toCodec2(0.019 + 0.037);
      case SubNetworkId.Kusama:
        return toCodec2(2e-3);
      case SubNetworkId.Polkadot:
        return toCodec2(0.019 + 0.037);
      default:
        return "0";
    }
